for a in 0..zero:
  for b in 0..one:
    for k in 1..limit:
      same-run: dp[a][b][x][k] = dp[a-1 or b-1][x][k-1]
      switch-run (k=1): dp[a][b][x][1] = sum over j=1..limit of dp[prev][opposite x][j]
    replace that sum with a prefix sum over k of the previous layer
answer = sum over k of dp[zero][one][0][k] + dp[zero][one][1][k]

code.cpp:
class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        const long long MOD = 1000000007LL;
        int Z = zero, O = one, L = limit;
        // p0[b][k], p1[b][k]: counts for previous layer a-1
        // s0[b][k], s1[b][k]: prefix sums over k of p0/p1
        vector<vector<long long>> p0(O + 1, vector<long long>(L + 1, 0)),
                                  p1(O + 1, vector<long long>(L + 1, 0)),
                                  s0(O + 1, vector<long long>(L + 1, 0)),
                                  s1(O + 1, vector<long long>(L + 1, 0));
        // layer a = 0: only all-ones arrays, dp[0][b][1][k] = 1 iff k == b <= limit
        for (int b = 1; b <= O && b <= L; ++b) p1[b][b] = 1;
        for (int b = 0; b <= O; ++b)
            for (int k = 1; k <= L; ++k)
                s1[b][k] = (s1[b][k - 1] + p1[b][k]) % MOD;
        for (int a = 1; a <= Z; ++a) {
            vector<vector<long long>> n0(O + 1, vector<long long>(L + 1, 0)),
                                      n1(O + 1, vector<long long>(L + 1, 0)),
                                      t0(O + 1, vector<long long>(L + 1, 0)),
                                      t1(O + 1, vector<long long>(L + 1, 0));
            for (int b = 0; b <= O; ++b) {
                if (b == 0) {
                    // all-zeros prefix: run at end is exactly a
                    if (a <= L) n0[0][a] = 1;
                } else {
                    for (int k = 1; k <= L; ++k) {
                        // dp[a][b][0][k]: append 0 to array with a-1 zeros, b ones
                        long long v0 = (k >= 2 ? p0[b][k - 1] : 0);
                        if (k == 1) v0 += s1[b][L];          // append 0 after run of 1s (prev layer)
                        // dp[a][b][1][k]: append 1 to array with a zeros, b-1 ones (current layer)
                        long long v1 = (k >= 2 ? n1[b - 1][k - 1] : 0);
                        if (k == 1) v1 += t0[b - 1][L];      // append 1 after run of 0s (current layer)
                        n0[b][k] = v0 % MOD;
                        n1[b][k] = v1 % MOD;
                    }
                }
                for (int k = 1; k <= L; ++k) {
                    t0[b][k] = (t0[b][k - 1] + n0[b][k]) % MOD;
                    t1[b][k] = (t1[b][k - 1] + n1[b][k]) % MOD;
                }
            }
            p0.swap(n0); p1.swap(n1); s0.swap(t0); s1.swap(t1);
        }
        return (int)((s0[O][L] + s1[O][L]) % MOD);
    }
};
